window.onload=init();let map=L.map("map").setView([46.866,3.333],6);function init(){let t=localStorage.getItem("theme")||"light";t&&updateTheme(t),fetch("../json/promo.json").then(t=>t.json()).then(t=>updateInformations(t))}function updateTheme(t){document.documentElement.setAttribute("data-bs-theme",t)}function setMarkers(t){t.forEach(t=>{if(t.coord){let e=t.coord.latitude,o=t.coord.longitude,n=`${t.lastname} ${t.name}`;L.marker([e,o]).bindPopup(n).addTo(map)}})}function updateInformations(t){document.querySelector("h1[nomPromo]").innerText=t.nomPromo}L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map),fetch("../json/promo.json").then(t=>t.json()).then(t=>setMarkers(t.apprenants));